with with_gaps as (select *, case when event_time - lag(event_time) over (partition by event_type order by event_time asc, id asc) > interval '60' day then 1 else 0 end as is_new_session from web_events), sessions_web_events as (select *, sum(is_new_session) over (partition by event_type order by event_time asc, id asc rows between unbounded preceding and current row) as burst_id from with_gaps) select case when is_new_session >= 1 then 'LARGE' else 'SMALL' end as is_new_session_tier, percentile_approx(is_new_session, array(0.25, 0.5, 0.75)) as is_new_session_quartiles, min(event_time) as first_event_time from sessions_web_events group by case when is_new_session >= 1 then 'LARGE' else 'SMALL' end;
